export const TOTAL_LEVELS = LEVELS.length;

export function levelByNumber(n) {
  return LEVELS.find(l => l.id === n) || LEVELS[0];
}

export function chapterFor(n) {
  return CHAPTERS.find(c => n >= c.range[0] && n <= c.range[1]) || CHAPTERS[0];
}

